// operations/commandOperations.ts
export function isOn(command: Command): boolean {
  return command.value === 'ON';
}

export function createTurnOnCommand(): Command {
  return { value: 'ON' };
}
```

This separation ensures that types are reusable across domains and functions are composable and testable in isolation.

